const board = $('Get Board Records').all();
const vendors = $('Get Vendor Accounts').all();
const byId = {};
for (const it of board) { const p = it.json; if (p && p.id) byId[p.id] = p; }
const vByEmail = {};
for (const it of vendors) { const p = it.json; if (!p || !p.properties) continue; const e = (p.properties['Email'] && p.properties['Email'].email) ? String(p.properties['Email'].email).toLowerCase().trim() : ''; if (e) vByEmail[e] = p; }
const prop = (p, n) => (p && p.properties && p.properties[n]) ? p.properties[n] : null;
const selName = (p, n) => { const x = prop(p, n); return x && x.select ? x.select.name : ''; };
const titleText = (p, n) => { const x = prop(p, n); return x && Array.isArray(x.title) ? x.title.map(t => t.plain_text).join('') : ''; };
const rich = (p, n) => { const x = prop(p, n); return x && Array.isArray(x.rich_text) ? x.rich_text.map(t => t.plain_text).join('') : ''; };
const emailOf = (p, n) => { const x = prop(p, n); return x && x.email ? x.email : ''; };
const numOf = (p, n) => { const x = prop(p, n); return (x && x.number != null) ? x.number : ''; };
const relIds = (p, n) => { const x = prop(p, n); return x && Array.isArray(x.relation) ? x.relation.map(r => r.id) : []; };
const out = [];
for (const it of board) {
  const req = it.json;
  if (selName(req, 'Record Type') !== 'Demand - Client Request') continue;
  if (selName(req, 'Status') !== 'Approved for RFQ') continue;
  const requestPageId = req.id;
  const requestName = titleText(req, 'Name') || 'Client Request';
  const city = selName(req, 'City');
  const category = selName(req, 'Property Category');
  const budget = numOf(req, 'Budget / Price');
  const sizeSqm = numOf(req, 'Size sqm');
  const seats = numOf(req, 'Seats / Capacity');
  const supplyIds = relIds(req, '\uD83D\uDD17 Matched Supply');
  for (const sid of supplyIds) {
    const sup = byId[sid];
    if (!sup) continue;
    const vendorEmail = emailOf(sup, 'Email');
    if (!vendorEmail) continue;
    const vendorName = rich(sup, 'Vendor Name') || titleText(sup, 'Name') || 'Partner';
    const supTitle = titleText(sup, 'Name');
    const supDistrict = rich(sup, 'District');
    const supPrice = numOf(sup, 'Budget / Price');
    const vacc = vByEmail[vendorEmail.toLowerCase().trim()] || null;
    const vendorPageId = vacc ? vacc.id : '';
    let noticeSent = false;
    if (vacc && vacc.properties && vacc.properties['Commission Notice Sent']) { noticeSent = vacc.properties['Commission Notice Sent'].checkbox === true; }
    const isNewVendor = !noticeSent;
    const needVendorUpdate = isNewVendor && vendorPageId !== '';
    const reqLines = [];
    reqLines.push('نوع العقار: ' + (category || '—'));
    reqLines.push('المدينة: ' + (city || '—'));
    if (sizeSqm) reqLines.push('المساحة المطلوبة: ' + sizeSqm + ' م²');
    if (seats) reqLines.push('عدد المقاعد/السعة: ' + seats);
    if (budget) reqLines.push('الميزانية التقديرية: ' + budget + ' ريال');
    const commissionBlock = isNewVendor ? ('\n\nملاحظة حول آلية التعامل:\nتعمل «بيزنس بارتنر» كوسيط بين العميل ومزوّدي العقارات ومساحات العمل. نحصل على عمولة قدرها 10% على الصفقة، ونطلب تضمينها ضمن عرض السعر الذي ترسلونه (أي أن يكون السعر شاملاً عمولة بيزنس بارتنر 10%).\n') : '';
    const supplyLine = supTitle ? ('\n\nالعرض المطابق لديكم: ' + supTitle + (supDistrict ? ' - ' + supDistrict : '') + (supPrice ? ' - ' + supPrice + ' ريال' : '')) : '';
    const body = 'مرحباً ' + vendorName + '،\n\nلدينا عميل يبحث عن عقار/مساحة عمل بالمواصفات التالية، ونودّ الحصول على عرض سعر منكم:\n\n' + reqLines.join('\n') + supplyLine + commissionBlock + '\n\nنرجو تزويدنا بعرض السعر شاملاً الشروط ومدة السريان في أقرب وقت.\n\nمع التحية،\nفريق بيزنس بارتنر | Business Partner\nbusiness@businesspartner.sa';
    const subject = 'طلب عرض سعر (RFQ) - ' + (category || 'عقار') + (city ? ' - ' + city : '');
    out.push({ json: { requestPageId, requestName, vendorEmail, vendorName, vendorPageId, isNewVendor, needVendorUpdate, subject, body } });
  }
}
return out;
